import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_kernel_code = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_avg_pool_sigmoid_sum_kernel(const float* conv_out, float* output, 
                                                int N, int C, int H, int W) {
    const int n = blockIdx.x;
    if (n >= N) return;

    const int H_pool = H / 2;
    const int W_pool = W / 2;
    const int elements_per_channel = H_pool * W_pool;
    const int total_elements = C * elements_per_channel;

    extern __shared__ float smem[];
    float thread_sum = 0.0f;

    for (int idx = threadIdx.x; idx < total_elements; idx += blockDim.x) {
        const int c = idx / elements_per_channel;
        const int pool_idx = idx % elements_per_channel;
        const int i = pool_idx / W_pool;
        const int j = pool_idx % W_pool;

        float avg = 0.0f;
        #pragma unroll
        for (int di = 0; di < 2; ++di) {
            #pragma unroll
            for (int dj = 0; dj < 2; ++dj) {
                const int h = i*2 + di;
                const int w = j*2 + dj;
                avg += conv_out[n * C*H*W + c * H*W + h * W + w];
            }
        }
        avg *= 0.25f;
        thread_sum += 1.0f / (1.0f + expf(-avg));
    }

    smem[threadIdx.x] = thread_sum;
    __syncthreads();

    // Block reduction
    for (int s = blockDim.x/2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            smem[threadIdx.x] += smem[threadIdx.x + s];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        output[n] = smem[0];
    }
}

torch::Tensor fused_op_cuda(torch::Tensor conv_out) {
    const int N = conv_out.size(0);
    const int C = conv_out.size(1);
    const int H = conv_out.size(2);
    const int W = conv_out.size(3);

    auto output = torch::zeros({N}, conv_out.options());
    const int threads = 256;
    const size_t smem = threads * sizeof(float);

    fused_avg_pool_sigmoid_sum_kernel<<<N, threads, smem>>>(
        conv_out.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, H, W
    );

    return output;
}
"""

cpp_wrapper = "torch::Tensor fused_op_cuda(torch::Tensor conv_out);"

fused_extension = load_inline(
    name='fused_extension',
    cpp_sources=cpp_wrapper,
    cuda_sources=fused_kernel_code,
    functions=['fused_op_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, pool_kernel_size):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)

    def forward(self, x):
        x = self.conv(x)
        x = fused_extension.fused_op_cuda(x)
        return x
